class RobotPet:
    def __init__(self, name, battery=100, mood="neutral"):
        self.name = name
        self.battery = battery
        self.mood = mood

    def speak(self):
        if self.battery < 20:
            return f"{self.name}: I need to recharge soon."
        if self.mood == "happy":
            return f"{self.name} is feeling happy!"
        return f"Hello, I am {self.name}."


class RobotCat(RobotPet):
    def speak(self):
        if self.battery < 20:
            return f"{self.name} is too tired to meow."
        if self.mood == "happy":
            return f"Purr! {self.name} is a happy kitty!"
        return f"Meow! I am {self.name}."


class RobotBird(RobotPet):
    def speak(self):
        if self.battery < 20:
            return f"{self.name}'s battery is low."
        if self.mood == "happy":
            return f"{self.name} sings a lovely song!"
        return f"Chirp! I am {self.name}."


class RobotDog(RobotPet):
    def speak(self):
        if self.battery < 20:
            return f"{self.name} needs a charge."
        if self.mood == "happy":
            return f"Best day ever! Woof from {self.name}!"
        return f"Woof! I am {self.name}."
